// Host-only exporter of an ALREADY ACCEPTED archived diagnostic workload.
// No physics evolution, GPU/browser execution, upload or publication occurs.
import assert from 'node:assert/strict';
import {readFileSync,writeFileSync,mkdirSync,existsSync,copyFileSync} from 'node:fs';
import {deserialize} from 'node:v8';
import {createHash} from 'node:crypto';
import {fileURLToPath} from 'node:url';
import {join,resolve} from 'node:path';
import {encodePortablePayload,decodePortablePayload,assertDecodedPortableRuntime,PORTABLE_RUNTIME_CONTRACT} from '../tests/resident-candidate-portable-payload.mjs';
const ROOT=fileURLToPath(new URL('../',import.meta.url)),hash=x=>createHash('sha256').update(x).digest('hex');
export const ACCEPTED_CALIBRATION_ARCHIVE=Object.freeze({directory:'/tmp/resident-raw-pc-isolated-native-v2',sourceHead:'135b1687f1ac0cfd58a3bc7208740757bf7b6114',hashes:Object.freeze({
 'manifest.json':'e6c4bdf623deba700506c26db7d23e3d5c2d7e05f4f6aecedaa3861d0e4a693e',
 'expected-manifest.json':'e21d497f6668649100baaabb15960e4778d226b69daf505c1ff330af864eb9be',
 'actual-manifest.json':'434b781acdf2b36a7ddc16119bf96e194300c4f1b44a99cc3cb199516f9961e8',
 'assertion.json':'befdbc84db2d03f9917ce2b44012a4e4a05cf95af3fe219789a69fc7a957535e',
 'runtime.v8':'4f2db833f116034d5ffe979b0d748418b4022f26c8906e0ed5cb13cf15b878dc',
 'expected.v8':'f68c428e2bd41c4c75733829f1a68457d86afe2bdeee631dff10b27bb529db67',
 'actual.v8':'19a56138982cdab5d4986f88b296d3545bbe327334fec37da35660492a3233bc'
})});
function readArchive(dir){const bytes=Object.fromEntries(Object.entries(ACCEPTED_CALIBRATION_ARCHIVE.hashes).map(([name,sha])=>{const b=readFileSync(join(dir,name));assert.equal(hash(b),sha,'exact accepted archive '+name);return[name,b];}));return{manifest:JSON.parse(bytes['manifest.json']),expectedManifest:JSON.parse(bytes['expected-manifest.json']),actualManifest:JSON.parse(bytes['actual-manifest.json']),certificate:JSON.parse(bytes['assertion.json']),runtime:deserialize(bytes['runtime.v8']),expected:deserialize(bytes['expected.v8']),actual:deserialize(bytes['actual.v8'])};}
export async function verifyAcceptedCalibrationArchive(dir=ACCEPTED_CALIBRATION_ARCHIVE.directory){
 const a=readArchive(dir),{manifest:m,expectedManifest:em,actualManifest:am,certificate:c,runtime:r,expected:e,actual:x}=a;
 assert.equal(c.stage,'strict-gate-passed');assert.equal(c.sourceHead,ACCEPTED_CALIBRATION_ARCHIVE.sourceHead);assert.equal(c.rows,6);assert.equal(c.frames,2);assert.equal(c.runs,2);assert.equal(c.strictFullBankComparisons,8);for(const key of['expectedSnapshotsUploaded','fullRest','native1024','hardwarePerformance'])assert.equal(c[key],false);
 for(const value of[m,em,am,r.identity,e,x])assert.equal(value.generationIdentity,c.generationIdentity);assert.equal(m.sourceHead,c.sourceHead);assert.equal(m.preStrikeIdentity,c.preStrikeIdentity);assert.equal(m.sourceIdentity,c.sourceIdentity);assert.equal(m.runtimeSha256,c.runtimeSha256);assert.equal(em.expectedSha256,c.expectedSha256);assert.equal(am.actualSha256,c.actualSha256);assertDecodedPortableRuntime(r);
 assert.equal(hash(r.input),m.rawInputSha256);assert.equal(hash(r.program),m.programSha256);assert.equal(hash(r.sharedGeometry),m.sharedGeometrySha256);assert.equal(hash(r.pc.bytecode),m.pipelineIdentity.bytecodeSha256);assert.equal(hash(r.pc.begin.code),m.pipelineIdentity.begin);for(const[k,s]of Object.entries(r.init.stages))assert.equal(hash(s.code),m.pipelineIdentity.initializer[k]);assert.deepEqual(r.pc.pipelines.map(s=>({name:s.name,sha256:hash(s.code)})),m.pipelineIdentity.owners);
 // Current test-only comparator is replayed directly on pinned archived output.
 // No rewritten source identity, old file-hash equality assumption, new expected
 // evolution or generated future bank is substituted for the accepted artifact.
 const{compareRawWorldPcResult}=await import('../tests/resident-candidate-raw-world-pc-compare.mjs');const fixture={frames:2,results:e.results,plan:{preStrikeIdentity:m.preStrikeIdentity}},plan={count:6,template:e.template,pc:{...e.pc,pipelines:{length:e.pc.pipelines}},sweeps:e.sweeps,source:{transport:e.transport},sourceMode:'owners'};
 assert.equal(x.runs.length,2);for(const[run,result]of x.runs.entries()){compareRawWorldPcResult({fixture,plan,words:result.words,run:run+1,artifactPath:join('/tmp','resident-calibration-export-mismatch-'+(run+1)+'.bin')});assert.equal(result.stats.mappings,1);assert.deepEqual(result.stats.executionGroups.map(g=>g.name),['initialize','pump']);if(run===1){assert.equal(result.stats.cache.coldCompiles,0);assert.deepEqual(result.words,x.runs[0].words);}}
 return a;
}
function writePayload(dir,name,value,archiveSha256){const encoded=encodePortablePayload(value),json=Buffer.from(JSON.stringify(encoded.metadata)+'\n'),binary=encoded.binary;assert.deepEqual(decodePortablePayload(JSON.parse(json),binary),value,name+' lossless portable roundtrip');writeFileSync(join(dir,name+'.json'),json);writeFileSync(join(dir,name+'.bin'),binary);return{json:name+'.json',binary:name+'.bin',jsonSha256:hash(json),binarySha256:hash(binary),jsonBytes:json.length,binaryBytes:binary.length,archiveSha256};}
export async function buildResidentCalibrationBundle({archiveDir=ACCEPTED_CALIBRATION_ARCHIVE.directory,outDir='/tmp/resident-calibration-bundle',includeAssets=true,runtimeModule,assetsDir=join(ROOT,'tools/resident-calibration-browser')}={}){
 const a=await verifyAcceptedCalibrationArchive(archiveDir),{manifest:m,runtime:r,expected:e,certificate:c,expectedManifest:em}=a;mkdirSync(outDir,{recursive:true});const runtime=writePayload(outDir,'runtime',r,c.runtimeSha256),expected=writePayload(outDir,'expected',e,c.expectedSha256);
 const calibration={kind:'resident-browser-calibration-bundle-v1',runtime,source:{sourceHead:m.sourceHead,preStrikeIdentity:m.preStrikeIdentity,sourceIdentity:m.sourceIdentity,generationIdentity:m.generationIdentity,sourceHashes:m.sourceHashes,sourceArtifactSha256:m.sourceArtifactSha256,rawRows:m.rawRows,rawInputSha256:m.rawInputSha256,programSha256:m.programSha256,sharedGeometrySha256:m.sharedGeometrySha256,pipelineIdentity:m.pipelineIdentity},workload:{count:6,frames:2,sweeps:2048,owners:16,initializerDispatches:68313,totalDispatches:101082,numericProfile:m.options.numericProfile,sourceCaps:PORTABLE_RUNTIME_CONTRACT.sourceCaps},plannedMatrix:[1,16,64,256,1024].map(count=>({count,status:'planned-unmeasured',acceptedPayload:false})),hardwarePerformance:false,numericallyQualified:false,defaultBackend:false,fullRest:false,native1024:false};
 const assertion={kind:'resident-browser-calibration-assertions-v1',expected,certificate:c,expectedGeneration:em.expectedGeneration,strictComparator:'compareRawWorldPcResult -> unchanged all11-group compareWorldBank',expectedLoadedOnlyAfterGpu:true};
 const assets={};if(includeAssets){
  copyFileSync(join(ROOT,'docs/resident-matched-calibration.md'),join(outDir,'CALIBRATION.md'));
  const runtimeSource=runtimeModule??join(ROOT,'tests/resident-candidate-browser-benchmark-runtime.mjs');for(const name of['index.html','app.mjs','report.mjs','style.css','report-template.json']){assert.ok(existsSync(join(assetsDir,name)),'local browser asset '+name);copyFileSync(join(assetsDir,name),join(outDir,name));}
  assert.ok(existsSync(runtimeSource),'pure browser runtime module');let code=readFileSync(runtimeSource,'utf8');code=code.replaceAll('./resident-candidate-portable-payload.mjs','./portable-payload.mjs');assert.doesNotMatch(code,/\bfrom\s*['"]node:/);writeFileSync(join(outDir,'runtime.mjs'),code);copyFileSync(join(ROOT,'tests/resident-candidate-portable-payload.mjs'),join(outDir,'portable-payload.mjs'));
  const{build}=await import('esbuild');const result=await build({entryPoints:[join(assetsDir,'comparison-entry.mjs')],outfile:join(outDir,'comparison.mjs'),bundle:true,platform:'browser',format:'esm',target:'es2022',metafile:true,logLevel:'silent'});for(const output of Object.values(result.metafile.outputs))assert.equal(output.imports.length,0,'all comparator dependencies bundled locally');
  for(const name of['index.html','app.mjs','report.mjs','style.css','report-template.json','CALIBRATION.md','runtime.mjs','portable-payload.mjs','comparison.mjs']){const bytes=readFileSync(join(outDir,name));assets[name]={sha256:hash(bytes),bytes:bytes.length};}for(const name of['index.html','app.mjs','report.mjs','style.css','runtime.mjs','portable-payload.mjs'])assert.doesNotMatch(readFileSync(join(outDir,name),'utf8'),/(?:\bfrom\s*['"]|\bimport\s*\(\s*['"]|(?:src|href)\s*=\s*['"])(?:https?:)?\/\//i,'no external runtime asset');
 }
 calibration.assets=assets;writeFileSync(join(outDir,'calibration-manifest.json'),JSON.stringify(calibration,null,2)+'\n');writeFileSync(join(outDir,'assertion-manifest.json'),JSON.stringify(assertion,null,2)+'\n');const report={kind:'resident-calibration-export-host-verification-v1',archiveDir,sourceHead:m.sourceHead,generationIdentity:m.generationIdentity,archiveHashes:ACCEPTED_CALIBRATION_ARCHIVE.hashes,runtime,expected,strictArchivedComparisons:8,portableRoundtrip:'deepStrictEqual',localAssetsComplete:includeAssets,assets,gpuExecuted:false,browserExecuted:false,uploaded:false,published:false,hardwarePerformance:false};writeFileSync(join(outDir,'export-verification.json'),JSON.stringify(report,null,2)+'\n');
 writeFileSync(join(outDir,'README.txt'),'Local diagnostic calibration only; no hardware measurements are included.\nServe locally with: python3 -m http.server 8765 --bind 127.0.0.1 --directory '+resolve(outDir)+'\nOpen http://localhost:8765/ only when explicitly authorized to run GPU calibration. Do not use file://; local modules/fetch require localhost or an authorized secure origin.\nRuntime and expected payloads are separate; expected data is loaded only after GPU work.\nCandidate matrix is planned/unmeasured, not fabricated accepted payloads.\nOnly fixed six rows/two pre-strike h run here; not full-rest or 1024-candidate throughput.\nUse identical bundle and timestamp mode on both adapters; cold compile is separate from warm timings.\nQueue-drain wall time is not GPU execution time; different CPU hosts change host overhead.\nreport-template.json contains no measurements and is intentionally rejected by the report comparator.\nSee CALIBRATION.md for exact timing, parity and qualification boundaries.\n');return{outDir,calibration,assertion,report};
}
if(process.argv[1]&&resolve(process.argv[1])===fileURLToPath(import.meta.url)){try{const flags=process.argv.slice(2).filter(x=>x.startsWith('--'));assert.ok(flags.every(x=>x==='--payload-only'),'known exporter flags');const args=process.argv.slice(2).filter(x=>!x.startsWith('--'));assert.ok(args.length<=2,'archive/output positional paths only');const result=await buildResidentCalibrationBundle({archiveDir:args[0]??ACCEPTED_CALIBRATION_ARCHIVE.directory,outDir:args[1]??'/tmp/resident-calibration-bundle',includeAssets:!flags.includes('--payload-only')});console.log(JSON.stringify(result.report));}catch(e){console.error(e);process.exitCode=1;}}
